class MainForm : Form
{
    private readonly StatusStrip _statusStrip;

    public MainForm()
    {
        _statusStrip = new StatusStrip();
        // .NET 9: StatusStrip default renderer changed. Set explicitly
        // to restore the .NET 8 System-rendered appearance.
        _statusStrip.RenderMode = ToolStripRenderMode.System;
        Controls.Add(_statusStrip);
    }
}

/// <summary>
/// Helper that safely calls IWindowsFormsEditorService.DropDownControl,
/// guarding against the .NET 9 nullability change (parameter is now non-nullable).
/// </summary>
static class EditorServiceExtensions
{
    public static void SafeDropDownControl(
        this IWindowsFormsEditorService service, Control? control)
    {
        if (control is null)
            return;

        service.DropDownControl(control);
    }
}

